from __future__ import annotations
import argparse, sys
from pathlib import Path
from ..dwg import ACadSharpProvider,DWGImporter
from .models import ValidationCase,ValidationThresholds
from .runner import RealDWGValidationRunner

def parser():
    p=argparse.ArgumentParser(prog='cbim-validate-dwg',description='Validate real DWG disciplines through ACadSharp -> CBIM -> IFC and federate results.')
    for d in ('architecture','structure','hydraulic','fire'):
        p.add_argument(f'--{d}',type=Path,help=f'{d} DWG file')
    p.add_argument('--output',type=Path,default=Path('cbim-validation-output'))
    p.add_argument('--bridge-exe',type=Path);p.add_argument('--bridge-project',type=Path)
    p.add_argument('--min-import-coverage',type=float,default=.85);p.add_argument('--min-recognition-rate',type=float,default=.45);p.add_argument('--min-confidence',type=float,default=.70)
    p.add_argument('--no-xref',action='store_true');p.add_argument('--ifc-backend',choices=('legacy','ifcopenshell','auto'),default='legacy',help='IFC authoring backend; legacy is the verified compatibility default');p.add_argument('--quiet-progress',action='store_true',help='suppress per-stage progress/timing messages')
    return p


def _print_progress(stage,status,elapsed,detail,*,quiet=False,stream=None):
    if quiet:return
    stream=stream or sys.stderr
    if status=='start':
        print(f'[CBIM] START {stage}',file=stream,flush=True)
        return
    suffix=' '.join(f'{k}={v}' for k,v in detail.items() if v not in (None,''))
    timing=f': {elapsed:.3f}s' if isinstance(elapsed,(int,float)) else ''
    print(f'[CBIM] DONE  {stage}{timing} {suffix}'.rstrip(),file=stream,flush=True)

def main(argv=None):
    args=parser().parse_args(argv);selected=[(d,getattr(args,d)) for d in ('architecture','structure','hydraulic','fire') if getattr(args,d)]
    if not selected: parser().error('provide at least one discipline DWG')
    provider=ACadSharpProvider(bridge_executable=args.bridge_exe,bridge_project=args.bridge_project)
    if not provider.available(): print('ACadSharp bridge unavailable. Build dwg-acadsharp-bridge first or pass --bridge-exe/--bridge-project.',file=sys.stderr);return 3
    importer=DWGImporter(provider);thresholds=ValidationThresholds(min_import_coverage=args.min_import_coverage,min_recognition_rate=args.min_recognition_rate,min_mean_confidence=args.min_confidence);cases=[]
    for d,path in selected:
        if not path.exists(): print(f'missing: {path}',file=sys.stderr);return 2
        cases.append(ValidationCase(name=f'{d}-{path.stem}',discipline=d,source_path=str(path),evidence_kind='real_project',thresholds=thresholds,resolve_xrefs=not args.no_xref))
    def progress(stage,status,elapsed,detail):
        _print_progress(stage,status,elapsed,detail,quiet=args.quiet_progress)
    batch=RealDWGValidationRunner(importer,output_dir=args.output,progress=progress,ifc_backend=args.ifc_backend).run_batch(cases,federate=True)
    print(batch.model_dump_json(indent=2,ensure_ascii=True));return 0 if batch.all_passed else 1

if __name__=='__main__':raise SystemExit(main())
